inline void read_int(int &ret) {
  cin >> ret;
  
}
struct Point{
  int x,y;
  Point(int x, int y) : x(x), y(y){}
  Point() {}
  bool operator<(const Point& other)const{
    return ((x!=other.x)?(x <other.x):(y<other.y));
  }
  bool operator==(const Point& other)const{
    return (x==other.x && y==other.y);
  }
};
ostream& operator<< (ostream& out, const Point& v) {
  out << "[" << v.x << ","  << v.y << "]";
  return out;
}
int manhattanDist(const Point& one, const Point& another){
  return abs(one.x-another.x) + abs(one.y-another.y);
}
struct Field{
  array<bitset<N>,N> flags;
  Field() : flags() {}
  bool test(int x, int y) const{
    return flags[y].test(x);
  }
  bool test(const Point& pos) const{
    return flags[pos.y].test(pos.x);
  }
  void set(int x, int y) {
    flags[y].set(x);
  }
  void set(const Point& pos) {
    flags[pos.y].set(pos.x);
  }
};
